(r/'tools/AnimalGoalsCheck.java').write_text('''import net.minecraft.world.entity.*;import net.minecraft.world.entity.animal.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.entity.player.Player;import org.millenaire.common.goal.*;import org.millenaire.common.goal.generic.*;import org.millenaire.common.entity.*;import org.millenaire.common.village.*;import org.millenaire.common.utilities.*;import net.minecraft.resources.ResourceLocation;import java.util.*;
public class AnimalGoalsCheck{
 static sun.misc.Unsafe unsafe;static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static class TestCow extends Cow{public int age;public boolean love,alive=true;public EntityType<?> kind=EntityType.COW;public TestCow(){super(EntityType.COW,null);}public int getAge(){return age;}public boolean isBaby(){return age<0;}public boolean isAlive(){return alive;}public boolean isInLove(){return love;}public void setInLove(Player p){love=true;}public void setTarget(LivingEntity e){}public EntityType<?> getType(){return kind;}}
 static TestCow cow(int age)throws Exception{TestCow c=(TestCow)unsafe.allocateInstance(TestCow.class);c.age=age;c.alive=true;c.kind=EntityType.COW;return c;}
 static MillVillager setup(int target,int food)throws Exception{WorldUtilities.animals=new ArrayList<>();MillVillager v=(MillVillager)unsafe.allocateInstance(MillVillager.class);v.level=(ServerLevel)unsafe.allocateInstance(ServerLevel.class);v.house=new Building();v.house.food=food;v.house.tags.add("cattle");v.house.resources.spawnTypes.add(new ResourceLocation("cow"));v.house.resources.spawns.add(new ArrayList<>(Collections.nCopies(target,new Point())));return v;}
 public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);unsafe=(sun.misc.Unsafe)f.get(null);var breed=new GoalBreedAnimals();var slaughter=new GoalGenericSlaughterAnimal();slaughter.animalKey=new ResourceLocation("cow");
 var v=setup(2,2);var a=cow(0);var b=cow(0);WorldUtilities.animals.addAll(List.of(a,b));check(breed.getDestination(v)!=null,"Ready pair selected");breed.performAction(v);check(a.love&&b.love&&v.house.food==0&&v.swings==2,"Pair consumes exactly two food");breed.performAction(v);check(v.swings==2,"No repeated feeding while in love");
 v=setup(2,2);a=cow(0);b=cow(0);WorldUtilities.animals.addAll(List.of(a,b));v.house.stale=true;breed.performAction(v);check(!a.love&&!b.love&&v.swings==0,"Failed food withdrawal does not breed");
 v=setup(1,2);a=cow(0);b=cow(0);WorldUtilities.animals.addAll(List.of(a,b));check(breed.getDestination(v)==null,"Herd at cap");breed.performAction(v);check(v.house.food==2&&!a.love,"Action rechecks cap");
 v=setup(2,2);a=cow(-100);b=cow(6000);WorldUtilities.animals.addAll(List.of(a,b));check(breed.getDestination(v)==null,"Baby and cooldown excluded");breed.performAction(v);check(v.house.food==2,"Ineligible animals not fed");
 v=setup(2,2);a=cow(0);b=cow(0);a.alive=false;WorldUtilities.animals.addAll(List.of(a,b));check(breed.getDestination(v)==null,"Dead animal cannot complete pair");
 v=setup(2,0);a=cow(0);b=cow(0);var child=cow(-1);WorldUtilities.animals.addAll(List.of(a,b,child));check(!slaughter.isDestPossibleSpecific(v,v.house),"Children not adult surplus");slaughter.performAction(v);check(v.target==null,"No slaughter at target");var extra=cow(0);WorldUtilities.animals.add(extra);check(slaughter.isDestPossibleSpecific(v,v.house),"Adult surplus allowed");slaughter.performAction(v);check(v.target!=child&&v.target!=null,"Adult selected");WorldUtilities.animals.remove(extra);v.target=null;slaughter.performAction(v);check(v.target==null,"Stale surplus rechecked");slaughter.aggressiveSlaughter=true;check(slaughter.isDestPossibleSpecific(v,v.house),"Aggressive half target");WorldUtilities.animals.remove(b);check(!slaughter.isDestPossibleSpecific(v,v.house),"Aggressive lower bound");
 slaughter.animalKey=new ResourceLocation("unknown_animal");check(!slaughter.isDestPossibleSpecific(v,v.house),"Unknown registry ID safe");v.house=null;check(breed.getDestination(v)==null&&breed.performAction(v)&&slaughter.performAction(v),"Missing house safe");
 System.out.println("PASS: actual animal goals with entity/world/storage fixtures: ready pair, exact food, stale food, herd cap, baby/cooldown/dead exclusions, adult surplus, stale target, aggressive threshold, unknown ID and null house. Live AI, births and combat untested.");
 }}''',encoding='utf-8')
